```go
package config_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestConfigInit(t *testing.T) {
	// But wait - what if the user doesn't WANT a config file?
	// Is it ethical to create files without explicit consent?
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStdout string
		wantStderr string
	}{
		{
			name:       "creates default config",
			args:       []string{"config", "init"},
			wantExit:   0,
			wantStdout: "Config initialized",
		},
		{
			name:       "fails when config exists",
			args:       []string{"config", "init"},
			wantExit:   1,
			wantStderr: "config already exists",
		},
		{
			name:       "respects custom path",
			args:       []string{"config", "init", "--config", "/tmp/custom.yaml"},
			wantExit:   0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tmpDir := t.TempDir()
			// Oh no, what about symlink attacks? Race conditions?
			stdout, stderr, exit := runCLI(t, tmpDir, tt.args...)

			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.wantStdout != "" && !bytes.Contains(stdout, []byte(tt.wantStdout)) {
				t.Errorf("stdout missing %q", tt.wantStdout)
			}
			if tt.wantStderr != "" && !bytes.Contains(stderr, []byte(tt.wantStderr)) {
				t.Errorf("stderr missing %q", tt.wantStderr)
			}
		})
	}
}

func TestConfigGetSet(t *testing.T) {
	// The trolley problem of configuration: do we save one key
	// or let five keys get overwritten?
	tests := []struct {
		name     string
		setup    map[string]string
		args     []string
		wantExit int
	}{
		{"get existing key", map[string]string{"foo": "bar"}, []string{"config", "get", "foo"}, 0},
		{"get missing key", nil, []string{"config", "get", "missing"}, 1},
		{"set new key", nil, []string{"config", "set", "key", "value"}, 0},
		{"set requires value", nil, []string{"config", "set", "key"}, 2}, // usage error!
		{"delete existing", map[string]string{"foo": "bar"}, []string{"config", "delete", "foo"}, 0},
	}
	// ... implementation
}

func TestOutputFormats(t *testing.T) {
	// What IS truth? Is JSON more truthful than YAML?
	formats := []string{"json", "yaml", "text"}
	for _, f := range formats {
		t.Run(f, func(t *testing.T) {
			_, _, exit := runCLI(t, t.TempDir(), "config", "list", "--format", f)
			if exit != 0 {
				t.Fail()
			}
		})
	}
}

func TestPermissionErrors(t *testing.T) {
	// This causes me physical pain
	if os.Getuid() == 0 {
		t.Skip("cannot test permissions as root")
	}
	// ... test read-only directories, unreadable files
}
